namespace Flow4Tech.Comandas.Domain;

public enum EstadoDoItem
{
    Lancado,
    Cancelado,
}

/// <summary>A batch of items sent together. <see cref="Id"/> is generated by the client (a repeat of it is never a second round); <see cref="ComandaVersao"/> is the comanda version this round produced.</summary>
public sealed record Rodada(Guid Id, Guid ComandaId, Guid UnidadeId, Guid EnviadaPor, DateTimeOffset EnviadaEm, DateTimeOffset? DesfeitaEm, int ComandaVersao);

/// <summary>An item of a comanda. Name and price are copies taken at launch. A cancelled item keeps its reason and who cancelled it.</summary>
public sealed record ItemDaComanda(
    Guid Id,
    Guid ComandaId,
    Guid RodadaId,
    int Posicao,
    Guid ProdutoId,
    string ProdutoNome,
    long PrecoCentavos,
    int Quantidade,
    string? Observacao,
    EstadoDoItem Estado,
    string? MotivoCancelamento,
    Guid? CanceladoPor,
    DateTimeOffset? CanceladoEm,
    IReadOnlyList<OpcaoDoItem>? OpcoesEscolhidas = null,
    TipoDoItem Tipo = TipoDoItem.Normal,
    string? MotivoDoTipo = null)
{
    /// <summary>The options picked for this item, name and price frozen at launch (empty when none).</summary>
    public IReadOnlyList<OpcaoDoItem> Opcoes => OpcoesEscolhidas ?? [];

    /// <summary>What one unit costs: the frozen product price plus the frozen price of every chosen option.</summary>
    public long PrecoUnitarioCentavos => PrecoCentavos + Opcoes.Sum(o => o.PrecoCentavos);

    /// <summary>The line at the frozen price, whatever its type: what a courtesy or a gift would have charged (kept for reports and the future stock write-off).</summary>
    public long ValorDeTabelaCentavos => PrecoUnitarioCentavos * Quantidade;

    /// <summary>What the line charges in cents: unit price with options times quantity, zero for a courtesy or a gift.</summary>
    public long TotalCentavos => Tipo == TipoDoItem.Normal ? ValorDeTabelaCentavos : 0;
}

/// <summary>An option chosen for an item. Name and price are copies taken at launch; a later change of the option never reaches the bill.</summary>
public sealed record OpcaoDoItem(Guid OpcaoId, Guid GrupoId, string Nome, long PrecoCentavos);

/// <summary>A round with its items, as the API answers it.</summary>
public sealed record RodadaComItens(Rodada Rodada, IReadOnlyList<ItemDaComanda> Itens);

/// <summary>Pure rules of rounds and items (no I/O; the clock is a parameter).</summary>
public static class RegrasDeRodada
{
    public const int ItensMaximoPorRodada = 50;

    public const int QuantidadeMaxima = 999;

    public const int TextoMaximo = 200;

    /// <summary>Fixed reason of an undone round (the waiter does not choose one).</summary>
    public const string MotivoDesfeito = "desfeito pelo garçom";

    public const string Outro = "outro";

    private static readonly Dictionary<string, string> Motivos = new(StringComparer.Ordinal)
    {
        ["cliente-desistiu"] = "cliente desistiu",
        ["erro-de-lancamento"] = "erro de lançamento",
        ["item-indisponivel"] = "item indisponível",
        [Outro] = Outro,
    };

    /// <summary>PostgreSQL keeps microseconds: an instant is cut to them BEFORE it is answered, so the first response and every repeat of it carry the very same value.</summary>
    public static DateTimeOffset Microssegundos(DateTimeOffset instante) => new(instante.Ticks - (instante.Ticks % 10), instante.Offset);

    public static bool QuantidadeValida(int quantidade) => quantidade is >= 1 and <= QuantidadeMaxima;

    /// <summary>Optional note: trimmed, 1 to 200, no control characters. Returns false when refused; <paramref name="valor"/> is null for an absent or blank note.</summary>
    public static bool TentarObservacao(string? bruto, out string? valor)
    {
        var texto = bruto?.Trim();
        valor = string.IsNullOrEmpty(texto) ? null : texto;
        return valor is null || (valor.Length <= TextoMaximo && !valor.Any(char.IsControl));
    }

    /// <summary>
    /// The stored reason of a cancelled item from the standard list code. 'outro' needs free text (the text is stored); the other codes ignore any text. Null when the code is not on the list
    /// or the free text is missing or invalid.
    /// </summary>
    public static string? MotivoDeItem(string? codigo, string? texto)
    {
        if (codigo is null || !Motivos.TryGetValue(codigo, out var palavra))
        {
            return null;
        }

        if (codigo != Outro)
        {
            return palavra;
        }

        return TentarObservacao(texto, out var livre) && livre is not null ? livre : null;
    }

    /// <summary>Undo is allowed only while less than <paramref name="janelaSegundos"/> have passed since the round was sent (server clock).</summary>
    public static bool DentroDaJanela(DateTimeOffset enviadaEm, DateTimeOffset agora, int janelaSegundos) =>
        agora >= enviadaEm && agora - enviadaEm <= TimeSpan.FromSeconds(janelaSegundos);

    public static string Palavra(EstadoDoItem estado) => estado == EstadoDoItem.Lancado ? "lancado" : "cancelado";

    public static EstadoDoItem EstadoDe(string palavra) => palavra switch
    {
        "lancado" => EstadoDoItem.Lancado,
        "cancelado" => EstadoDoItem.Cancelado,
        _ => throw new ArgumentOutOfRangeException(nameof(palavra)),
    };

    /// <summary>The consumption of the comanda in cents: items still launched, price with options times quantity (cancelled items leave it).</summary>
    public static long Consumo(IEnumerable<ItemDaComanda> itens)
    {
        ArgumentNullException.ThrowIfNull(itens);
        return itens.Where(i => i.Estado == EstadoDoItem.Lancado).Sum(i => i.TotalCentavos);
    }
}
